//! The part model generated by atf15xx-arch from every Atmel BSDL file the prjbureau submodule
//! ships, and against facts measured on the bench chip.

use atf15xx_tool::dbg::part::{CellKind, Part};

const PARTS: [&str; 12] = [
    "ATF1502AS-PLCC44", "ATF1502AS-TQFP44", "ATF1504AS-PLCC44", "ATF1504AS-TQFP44", "ATF1504AS-PLCC68", "ATF1504AS-PLCC84",
    "ATF1504AS-PQFP100", "ATF1504AS-TQFP100", "ATF1508AS-PLCC84", "ATF1508AS-TQFP100", "ATF1508AS-PQFP100", "ATF1508AS-PQFP160",
];

#[test]
fn every_part_builds_and_agrees_with_arch() {
    for name in PARTS {
        let p = Part::load(name).unwrap_or_else(|e| panic!("{name}: {e:#}"));
        assert_eq!(p.ir_len, 10, "{name}");
        for op in ["EXTEST", "SAMPLE", "IDCODE", "BYPASS"] {
            p.opcode(op).unwrap();
        }
        let nmc = p.macrocells();
        assert_eq!(p.length, nmc as usize * 2 + p.cells.iter().filter(|c| c.kind == CellKind::In).count(), "{name}");
        for mc in 1..=nmc {
            assert!(p.mc_cell(mc, CellKind::Oe).is_some() && p.mc_cell(mc, CellKind::Out).is_some(), "{name} MC{mc}");
        }
        assert_eq!(p.cells.iter().filter(|c| c.dedicated.is_some()).count(), 4, "{name}");
        // IDCODE 0x0150_n03f with n = 2 / 4 / 8 for the 1502 / 1504 / 1508 (and n + 1: the BSDL's `X` bit)
        let fam: u32 = name[3..7].parse().unwrap();
        let id = 0x0150_003f | (fam % 10) << 12;
        assert_eq!(p.idcodes, vec![id, id | 0x1000], "{name}");
    }
}

/// The ATF1508AS-PLCC84 cell map agrees with what SAMPLE/EXTEST showed on the bench chip. (Until
/// 2026-11-25 the whole bench map was committed as JSON; the generated map equalled it in all 352
/// cells when it was retired. These are the facts the bench established directly.)
#[test]
fn bench_facts() {
    let part = Part::load("ATF1508AS-PLCC84").unwrap();
    assert_eq!(part.length, 352);
    let named = |bit: usize| {
        let c = part.cells.iter().find(|c| c.bit == bit).unwrap();
        (c.name(), c.pin)
    };
    for (bit, name, pin) in [
        (0, "OE1", Some(84)),
        (1, "GCLK1", Some(83)),
        (2, "MC128.in", Some(81)),
        (3, "MC126.in", Some(80)),
        (4, "MC125.in", Some(79)),
        (5, "MC124.in", None),
        (94, "GCLK2", Some(2)),
        (95, "GCLR", Some(1)),
        (349, "MC15.out", None),
        (350, "MC16.oe", Some(4)),
        (351, "MC16.out", Some(4)),
    ] {
        assert_eq!(named(bit), (name.to_string(), pin), "cell {bit}");
    }
    for (k, v) in [("EXTEST", 0b0000000000), ("SAMPLE", 0b0001010101), ("IDCODE", 0b0001011001), ("BYPASS", 0b1111111111)] {
        assert_eq!(part.opcode(k).unwrap(), v, "{k}");
    }
    assert!(part.idcodes.contains(&0x0150_803f));
}
